document.addEventListener("DOMContentLoaded", function () {
  var slider = document.querySelector('.n2-ss-slider');
  if (!slider) return;

  var slides = slider.querySelectorAll('.n2-ss-slide');
  var pagination = document.createElement('div');
  pagination.className = 'custom-pagination';

  slides.forEach(function(slide, i) {
    var span = document.createElement('span');
    span.innerText = (i + 1).toString().padStart(2, '0');
    if (i === 0) span.classList.add('active');
    pagination.appendChild(span);
  });

  slider.appendChild(pagination);

  var observer = new MutationObserver(function(mutations) {
    mutations.forEach(function(mutation) {
      var activeIndex = Array.from(slides).findIndex(s => s.classList.contains('n2-ss-slide-active'));
      pagination.querySelectorAll('span').forEach(function(sp, idx) {
        sp.classList.toggle('active', idx === activeIndex);
      });
    });
  });

  observer.observe(slider, { attributes: true, subtree: true, attributeFilter: ['class'] });
});
